Source pattern:
```jsx
function LiveClock() {
  const [time, setTime] = useState('—');
  useEffect(() => {
    const fmt = () => {
      const d = new Date();
      const hh = d.getHours();
      const mm = d.getMinutes().toString().padStart(2, '0');
      const ampm = hh >= 12 ? 'pm' : 'am';
      const h12 = hh % 12 || 12;
      setTime(`${h12}:${mm}${ampm}`);
    };
    fmt();
    const id = setInterval(fmt, 30000);
    return () => clearInterval(id);
  }, []);
  return <span>{time}</span>;
}
```

